INSERT INTO countries (code, name, flag, rabies_status, authority_name, authority_url, import_summary, quarantine_note, accepted_modes, pet_airports) VALUES ('CA', 'Canada', '🇨🇦', 'controlled', 'Canadian Food Inspection Agency (CFIA)', 'https://inspection.canada.ca/en/importing-food-plants-or-animals/pets', 'Bringing a pet cat or dog into Canada is fairly simple: most need a rabies vaccination certificate and a quick check at the border.', 'No quarantine for pet cats and dogs that meet the requirements.', '["cabin","checked","cargo"]', 'Any major international airport (e.g. Toronto YYZ, Vancouver YVR, Montréal YUL)');
INSERT INTO countries (code, name, flag, rabies_status, authority_name, authority_url, import_summary, quarantine_note, accepted_modes, pet_airports) VALUES ('HK', 'Hong Kong', '🇭🇰', 'free', 'Agriculture, Fisheries and Conservation Department (AFCD)', 'https://www.afcd.gov.hk/english/quarantine/qua_ie/qua_ie_ipab/qua_ie_ipab_idc/qua_ie_ipab_idc.html', 'Hong Kong sorts countries into groups by rabies risk. You need a Special Permit from AFCD before travel, a vet health certificate signed close to departure, and your pet must fly in as cargo.', 'Pets from Group I and Group II places that meet every permit condition usually skip quarantine. Pets from Group III places face quarantine (30 days for Group IIIA, longer for others).', '["cargo"]', 'Hong Kong International Airport (HKG) — animals are collected after AFCD inspection');
INSERT INTO countries (code, name, flag, rabies_status, authority_name, authority_url, import_summary, quarantine_note, accepted_modes, pet_airports) VALUES ('US', 'United States', '🇺🇸', 'controlled', 'CDC (dogs) and USDA APHIS', 'https://www.cdc.gov/importation/dogs/index.html', 'Since August 2024 every dog entering the US must be at least 6 months old, microchipped and have a CDC Dog Import Form receipt. Cats have no federal paperwork, but some states and airlines ask for a rabies certificate.', 'No quarantine for healthy pets from low-risk countries. Hawaii has its own much stricter rules.', '["cabin","checked","cargo"]', 'Most international airports; dogs from high-risk countries must use specific airports');
INSERT INTO countries (code, name, flag, rabies_status, authority_name, authority_url, import_summary, quarantine_note, accepted_modes, pet_airports) VALUES ('GB', 'United Kingdom', '🇬🇧', 'free', 'Animal and Plant Health Agency (APHA) / GOV.UK', 'https://www.gov.uk/bring-pet-to-great-britain', 'Great Britain needs a microchip, a rabies vaccine at least 21 days before travel, an animal health certificate, and (for dogs) a tapeworm treatment 1–5 days before arrival. Pets must arrive by an approved route, which for flights normally means cargo.', 'No quarantine if all rules are met; pets that fail the checks can be quarantined at your cost.', '["cargo"]', 'Approved routes only — e.g. London Heathrow Animal Reception Centre');
INSERT INTO countries (code, name, flag, rabies_status, authority_name, authority_url, import_summary, quarantine_note, accepted_modes, pet_airports) VALUES ('EU', 'European Union', '🇪🇺', 'controlled', 'European Commission (EU pet travel rules, Reg. 576/2013)', 'https://food.ec.europa.eu/animals/movement-pets_en', 'Coming from a "listed" country (like Canada, the US, the UK, Hong Kong or Japan) you need a microchip, a rabies vaccine at least 21 days old and an EU animal health certificate endorsed by the government vet. Some countries add their own rules (e.g. tapeworm treatment for dogs to Ireland, Finland, Malta).', 'No quarantine if all rules are met.', '["cabin","checked","cargo"]', 'Must enter through a travellers’ point of entry with a customs pet check');
INSERT INTO countries (code, name, flag, rabies_status, authority_name, authority_url, import_summary, quarantine_note, accepted_modes, pet_airports) VALUES ('AU', 'Australia', '🇦🇺', 'free', 'Department of Agriculture, Fisheries and Forestry (DAFF)', 'https://www.agriculture.gov.au/biosecurity-trade/cats-dogs', 'Australia is one of the strictest places to bring a pet. From most countries you need a rabies blood test (RNATT) at least 180 days before export, an import permit, many vet treatments and a minimum 10-day stay at the Mickleham quarantine station in Melbourne.', 'Minimum 10 days at the Mickleham Post-Entry Quarantine facility (longer, e.g. 30 days, if requirements such as the identity check are not met).', '["cargo"]', 'Melbourne (MEL) only, then transfer to Mickleham quarantine');
INSERT INTO countries (code, name, flag, rabies_status, authority_name, authority_url, import_summary, quarantine_note, accepted_modes, pet_airports) VALUES ('SG', 'Singapore', '🇸🇬', 'free', 'Animal & Veterinary Service (AVS), NParks', 'https://avs.nparks.gov.sg/pets/importing-exporting-a-pet/import/dogs-and-cats/', 'Singapore groups countries by rabies risk (rules were updated in 2024). You need a pet licence and an import licence from AVS before arrival, a vet health certificate endorsed by the government, and your pet arrives as cargo at Changi.', 'Often no quarantine for compliant pets from low-risk countries, but this depends on your origin’s category — check the AVS schedule for your country.', '["cargo"]', 'Changi Airport (SIN) — Changi Animal and Plant Quarantine');
INSERT INTO countries (code, name, flag, rabies_status, authority_name, authority_url, import_summary, quarantine_note, accepted_modes, pet_airports) VALUES ('JP', 'Japan', '🇯🇵', 'free', 'Animal Quarantine Service (AQS), MAFF', 'https://www.maff.go.jp/aqs/english/animal/dog/import-other.html', 'From most countries Japan needs a microchip, two rabies shots, a rabies blood test, and then a 180-day wait from the blood test before arrival. You must also notify the Animal Quarantine Service at least 40 days before arrival.', 'If every step is done correctly, the inspection at the airport takes up to about 12 hours. If not, quarantine can last up to 180 days.', '["cabin","checked","cargo"]', 'Airports with an Animal Quarantine Service office (e.g. Narita NRT, Haneda HND, Kansai KIX)');
