INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('gen-vet-consult', '*', 'general', 'both', NULL, 200, NULL, 0, '[]', 0, 0, 'Book a "travel planning" visit with your vet', 'Sit down with your vet and walk through this checklist together.', 'Your vet will sign most of the paperwork. Many countries require the vet to be officially approved (accredited) for export certificates, so it is worth checking early that yours is.', 'Bring this plan to the appointment. Ask: "Are you accredited to sign export health certificates?", "Is my pet’s microchip the international (ISO) type?", and "Are the rabies vaccines up to date?" Ask for copies of all past vaccination records.', 'If your vet is not accredited, ask them to recommend one who is — you can keep your regular vet for everything else.', 'A normal consultation fee', NULL, 'general', '2026-11-22', 10);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('gen-snub-check', '*', 'general', 'both', '{"snubNosed":true}', 150, NULL, 0, '[]', 0, 0, 'Ask your vet if your flat-faced pet is fit to fly', 'Get a fitness-to-fly check for a snub-nosed (brachycephalic) breed.', 'Flat-faced cats and dogs (Persian, Himalayan, Exotic Shorthair, Pug, French Bulldog, etc.) have narrower airways and are more at risk from heat and stress in the air. Several airlines refuse them in the hold.', 'Ask your vet to check breathing and heart health and to write a short "fit to fly" letter. Some airlines require a larger crate (one size up) for these breeds.', NULL, NULL, NULL, 'general', '2026-11-22', 11);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('gen-agent', '*', 'general', 'both', NULL, 120, NULL, 0, '[]', 0, 0, 'Decide whether to use a pet relocation agent', 'Choose between doing everything yourself or hiring a professional pet shipper.', 'When pets must fly as cargo, many airlines only take bookings from professional shippers. For example, since September 2025 Cathay Cargo only accepts pet bookings from IPATA/ATA members, IATA freight forwarders or people with IATA live-animal training.', 'Get 2–3 quotes from members of IPATA (the International Pet and Animal Transportation Association). Ask exactly what is included: paperwork, the crate, airport drop-off, customs clearance and delivery at the other end.', 'Agents cost more, but for cargo-only destinations (Hong Kong, UK, Australia, Singapore) they are often the only practical way to book.', 'Varies widely — often a few thousand dollars including the flight', NULL, 'general', '2026-11-22', 12);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('gen-crate-buy', '*', 'general', 'both', NULL, 45, NULL, 0, '[]', 0, 0, 'Buy an airline-approved (IATA) travel crate', 'Get a sturdy hard-plastic crate that meets IATA Live Animal Regulations.', 'Airlines reject crates that are too small or the wrong type at check-in, and your pet would miss the flight.', 'Your pet must be able to stand, turn around and lie down naturally. Look for: rigid plastic, metal door, metal nuts and bolts (not plastic clips), ventilation on all sides, no wheels (or wheels removed), and a water and food bowl attached to the door that can be filled from outside.', 'Measure your pet standing up (nose to base of tail, and floor to top of the head or ears) and compare with the airline’s size chart.', 'Roughly $80–$300 depending on size', NULL, 'general', '2026-11-22', 13);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('gen-crate-train', '*', 'general', 'both', NULL, 3, NULL, 30, '["gen-crate-buy"]', 0, 0, 'Crate-train your pet', 'Help your pet feel safe and calm inside the travel crate.', 'A pet that is used to its crate is much less stressed on a long journey.', 'Leave the crate open at home with a familiar blanket. Feed meals inside it. Slowly build up to closing the door for short periods, then longer ones, then short car rides.', 'Do not sedate your pet for the flight unless your vet specifically advises it — most airlines refuse sedated animals.', NULL, NULL, 'general', '2026-11-22', 14);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('gen-book-flight', '*', 'general', 'both', NULL, 21, NULL, 7, '["hk-permit","au-permit","sg-import-licence","gb-approved-route"]', 0, 1, 'Book your pet’s flight', 'Reserve space for your pet on a flight that matches your arrival date (see the Airlines tab).', 'Pet spaces are limited on every aircraft, and cargo bookings are often only confirmed about a month before departure.', 'Pick an airline from the Airlines tab. If your pet flies as cargo, book through the airline’s cargo team or your pet relocation agent. If it flies in the cabin or as checked baggage, call the airline after buying your own ticket to add the pet.', 'Choose nonstop flights where you can, and avoid the hottest part of the day in summer.', 'Cargo: often $1,000–$3,000+ for long-haul; cabin or checked: often $100–$500 each way', NULL, 'general', '2026-11-22', 15);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('gen-docs-folder', '*', 'general', 'both', NULL, 2, NULL, 0, '[]', 0, 0, 'Put together a travel document folder', 'Keep every original document plus two photocopies in one waterproof folder.', 'Officials at both ends will want to see originals. Missing one page can delay your pet’s release.', 'Include: permit or licence, signed health certificate, rabies and other vaccine certificates, microchip record, lab results, airline booking, and your contact details at the destination. Tape a copy in a plastic sleeve on top of the crate.', NULL, NULL, NULL, 'general', '2026-11-22', 16);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('gen-travel-day', '*', 'general', 'both', NULL, 0, 2, 0, '[]', 0, 0, 'Travel day', 'Drop your pet off and get through the journey calmly.', 'A well-prepared drop-off avoids last-minute problems.', 'Give a light meal about 4–6 hours before the flight and offer water up to drop-off. Label the crate "LIVE ANIMAL" with arrows showing which way is up, your pet’s name and both phone numbers. Cargo drop-off is usually 4–6 hours before departure at the airline’s cargo terminal (not the passenger terminal).', 'Freeze the water bowl the night before so it melts slowly and does not spill.', NULL, NULL, 'general', '2026-11-22', 17);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('gen-after-vet', '*', 'general', 'both', NULL, -14, NULL, 0, '[]', 0, 0, 'Register with a local vet', 'Find a vet near your new home and book a check-up.', 'Travel is stressful. A check-up confirms your pet is settling in well and starts a local medical record.', 'Bring all your travel documents and vaccine history to the first appointment.', NULL, NULL, NULL, 'general', '2026-11-22', 18);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('gen-after-microchip', '*', 'general', 'both', NULL, -7, NULL, 0, '[]', 0, 0, 'Update your microchip contact details', 'Change the address and phone number on your pet’s microchip registration.', 'If your pet ever gets lost, the shelter will call the number on the chip registration.', 'Log in to the microchip registry (your vet can tell you which one) and update your new address and local phone number.', NULL, NULL, NULL, 'general', '2026-11-22', 19);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('ca-cfia-book', 'CA', 'export', 'both', NULL, 30, NULL, 0, '[]', 0, 0, 'Book your CFIA endorsement appointment', 'Reserve a time with your local CFIA office for endorsement of the health certificate.', 'The health certificate often has to be signed only a few days before departure, so the CFIA appointment has to fit into a small window. Booking early avoids a scramble.', 'Find your nearest CFIA animal health office on the CFIA website and ask how they accept export certificates (in person, by courier or electronically) and how long they take.', NULL, NULL, 'https://inspection.canada.ca/en/animal-health/terrestrial-animals/exports/pets', 'general', '2026-11-22', 0);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('ca-cfia-endorse', 'CA', 'export', 'both', '{"destCodes":["HK","GB","EU","AU","JP","SG"]}', 1, NULL, 0, '["hk-health-cert","gb-ahc","eu-ahc","au-health-cert","jp-health-cert","sg-health-cert","ca-health-cert","us-health-cert"]', 0, 1, 'Get the health certificate endorsed by CFIA', 'After your vet signs the health certificate, the Canadian Food Inspection Agency (CFIA) must check and endorse (officially stamp or sign) it.', 'Most destinations only accept a health certificate that a government vet in your departure country has endorsed. Without it your pet can be refused entry.', 'Take (or courier) the original certificate signed by your accredited vet, plus the rabies certificate and microchip record, to your CFIA office. Check that every page is stamped before you leave.', NULL, 'A CFIA fee applies (see the CFIA fee schedule)', 'https://inspection.canada.ca/en/animal-health/terrestrial-animals/exports/pets', 'general', '2026-11-22', 1);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('us-aphis-endorse', 'US', 'export', 'both', '{"destCodes":["HK","GB","EU","AU","JP","SG"]}', 1, NULL, 0, '["hk-health-cert","gb-ahc","eu-ahc","au-health-cert","jp-health-cert","sg-health-cert","ca-health-cert","us-health-cert"]', 0, 1, 'Get the health certificate endorsed by USDA APHIS', 'After your vet signs the health certificate, USDA APHIS (the US government animal health service) must check and endorse (officially stamp or sign) it.', 'Most destinations only accept a health certificate that a government vet in your departure country has endorsed. Without it your pet can be refused entry.', 'Your USDA-accredited vet usually submits the certificate electronically through VEHCS. APHIS checks it and endorses it, either electronically or on paper. Ask your vet which applies for your destination.', NULL, 'An APHIS endorsement fee applies (higher if lab tests are included)', 'https://www.aphis.usda.gov/pet-travel/us-to-another-country-export', 'general', '2026-11-22', 2);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('gb-ehc', 'GB', 'export', 'both', '{"destCodes":["HK","GB","EU","AU","JP","SG"]}', 1, NULL, 0, '["hk-health-cert","gb-ahc","eu-ahc","au-health-cert","jp-health-cert","sg-health-cert","ca-health-cert","us-health-cert"]', 0, 1, 'Get an export health certificate (EHC) through APHA', 'After your vet signs the health certificate, an Official Veterinarian (OV) using the APHA export health certificate must check and endorse (officially stamp or sign) it.', 'Most destinations only accept a health certificate that a government vet in your departure country has endorsed. Without it your pet can be refused entry.', 'Your vet applies to APHA online for the right export health certificate for your destination. APHA sends it to an Official Veterinarian, who examines your pet and signs it.', NULL, 'Vet / Official Veterinarian fees apply', 'https://www.gov.uk/guidance/export-health-certificates', 'general', '2026-11-22', 3);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('eu-endorse', 'EU', 'export', 'both', '{"destCodes":["HK","GB","EU","AU","JP","SG"]}', 1, NULL, 0, '["hk-health-cert","gb-ahc","eu-ahc","au-health-cert","jp-health-cert","sg-health-cert","ca-health-cert","us-health-cert"]', 0, 1, 'Get the certificate endorsed by your country’s official vet', 'After your vet signs the health certificate, the official (state) veterinary service of the EU country you are leaving must check and endorse (officially stamp or sign) it.', 'Most destinations only accept a health certificate that a government vet in your departure country has endorsed. Without it your pet can be refused entry.', 'Each EU country does this slightly differently. Ask your vet who the competent authority is (e.g. the regional veterinary office) and book early.', NULL, 'Varies by country', 'https://food.ec.europa.eu/animals/movement-pets_en', 'general', '2026-11-22', 4);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('au-export-endorse', 'AU', 'export', 'both', '{"destCodes":["HK","GB","EU","AU","JP","SG"]}', 1, NULL, 0, '["hk-health-cert","gb-ahc","eu-ahc","au-health-cert","jp-health-cert","sg-health-cert","ca-health-cert","us-health-cert"]', 0, 1, 'Get the export certificate endorsed by DAFF', 'After your vet signs the health certificate, a government vet from the Department of Agriculture, Fisheries and Forestry (DAFF) must check and endorse (officially stamp or sign) it.', 'Most destinations only accept a health certificate that a government vet in your departure country has endorsed. Without it your pet can be refused entry.', 'Lodge a Notice of Intention to export with DAFF, then book a DAFF vet inspection close to departure. Ask for the destination country’s certificate to be endorsed.', NULL, 'DAFF export fees apply', 'https://www.agriculture.gov.au/biosecurity-trade/export/controlled-goods/live-animals/companion-animals', 'general', '2026-11-22', 5);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('jp-aqs-export-notice', 'JP', 'export', 'both', NULL, 8, NULL, 0, '[]', 0, 1, 'Tell Japan’s Animal Quarantine Service you are leaving', 'Notify the Animal Quarantine Service (AQS) office at your departure airport.', 'In Japan, pets leaving the country also go through an export quarantine inspection, and AQS needs advance notice.', 'Contact the AQS office at your departure airport (e.g. Narita or Haneda) at least 7 days before departure.', NULL, NULL, 'https://www.maff.go.jp/aqs/english/animal/dog/export.html', 'general', '2026-11-22', 6);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('jp-aqs-export', 'JP', 'export', 'both', '{"destCodes":["HK","GB","EU","AU","JP","SG"]}', 1, NULL, 0, '["hk-health-cert","gb-ahc","eu-ahc","au-health-cert","jp-health-cert","sg-health-cert","ca-health-cert","us-health-cert","jp-aqs-export-notice"]', 0, 1, 'Export inspection by Animal Quarantine Service', 'After your vet signs the health certificate, the Animal Quarantine Service at the airport must check and endorse (officially stamp or sign) it.', 'Most destinations only accept a health certificate that a government vet in your departure country has endorsed. Without it your pet can be refused entry.', 'Arrive early on the day of travel (or the day before, as told by AQS) with your pet and paperwork. AQS inspects your pet and issues the export quarantine certificate.', NULL, 'Usually free', 'https://www.maff.go.jp/aqs/english/animal/dog/export.html', 'general', '2026-11-22', 7);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('sg-export-licence', 'SG', 'export', 'both', '{"destCodes":["HK","GB","EU","AU","JP","SG"]}', 1, NULL, 0, '["hk-health-cert","gb-ahc","eu-ahc","au-health-cert","jp-health-cert","sg-health-cert","ca-health-cert","us-health-cert"]', 0, 1, 'Apply for an AVS export licence and certificate endorsement', 'After your vet signs the health certificate, the Animal & Veterinary Service (AVS) must check and endorse (officially stamp or sign) it.', 'Most destinations only accept a health certificate that a government vet in your departure country has endorsed. Without it your pet can be refused entry.', 'Apply for an export licence on the AVS licensing portal and arrange for the health certificate to be endorsed by AVS.', NULL, 'AVS licence fee applies', 'https://avs.nparks.gov.sg/pets/importing-exporting-a-pet/export/', 'general', '2026-11-22', 8);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('hk-export-cert', 'HK', 'export', 'both', '{"destCodes":["HK","GB","EU","AU","JP","SG"]}', 1, NULL, 0, '["hk-health-cert","gb-ahc","eu-ahc","au-health-cert","jp-health-cert","sg-health-cert","ca-health-cert","us-health-cert"]', 0, 1, 'Get an AFCD export health certificate', 'After your vet signs the health certificate, AFCD (Hong Kong’s Agriculture, Fisheries and Conservation Department) must check and endorse (officially stamp or sign) it.', 'Most destinations only accept a health certificate that a government vet in your departure country has endorsed. Without it your pet can be refused entry.', 'Apply to AFCD for an export health certificate for your destination. Make an appointment for your pet to be examined by an AFCD vet, then collect the endorsed certificate.', NULL, 'AFCD fee applies', 'https://www.afcd.gov.hk/english/quarantine/qua_ie/qua_ie_eapao/qua_ie_eapao_ioahc/qua_ie_eapao_ioahc.html', 'reviewed', '2026-11-22', 9);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('hk-microchip', 'HK', 'import', 'both', NULL, 5, NULL, 0, '[]', 0, 1, 'Make sure your pet has an ISO microchip', 'Your pet needs a 15-digit microchip that meets the international ISO 11784/11785 standard.', 'The microchip is how officials in Hong Kong check that the animal in the crate is the same one on all the paperwork. It must be put in before the rabies vaccine, so the vaccine is linked to the right animal.', 'Ask your vet to scan your pet and confirm the chip is ISO-standard. If it isn’t, or there is no chip, your vet can implant one in a quick, routine visit.', 'Make sure the microchip number is written the same way on every document.', 'About $50–$100 if a new chip is needed', 'https://www.afcd.gov.hk/english/quarantine/qua_ie/qua_ie_ipab/qua_ie_ipab_idc/qua_ie_ipab_idc.html', 'reviewed', '2026-11-22', 20);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('hk-rabies', 'HK', 'import', 'both', '{"originGroups":["II"]}', 30, 365, 0, '["hk-microchip"]', 0, 1, 'Rabies vaccination (30 days to 1 year before arrival)', 'Your pet needs a rabies vaccine given at least 30 days, and no more than 1 year, before arriving in Hong Kong.', 'Hong Kong is rabies-free and wants to keep it that way. The 30-day wait gives the vaccine time to take effect.', 'Ask your vet for a rabies vaccine and a signed rabies certificate showing the date, vaccine brand, batch number and the microchip number. If your pet’s current vaccine will be older than 1 year on arrival day, get a booster now.', 'The vaccine must be given after the microchip was implanted (or on the same day).', 'About $40–$100', 'https://www.afcd.gov.hk/english/quarantine/qua_ie/qua_ie_ipab/qua_ie_ipab_idc/qua_ie_ipab_idc.html', 'reviewed', '2026-11-22', 21);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('hk-dog-vaccines', 'HK', 'import', 'dog', NULL, 14, 365, 0, '["hk-microchip"]', 0, 1, 'Dog vaccines: distemper, hepatitis and parvovirus', 'Dogs also need to be vaccinated against canine distemper, hepatitis and parvovirus (often given together as a "DHPP" shot).', 'These are serious infectious diseases, and Hong Kong’s permit conditions ask for proof of protection.', 'Ask your vet to check the date of the last combination shot. If it is older than a year, or less than 14 days before travel, plan a booster.', NULL, 'About $50–$100', 'https://www.afcd.gov.hk/english/quarantine/qua_ie/qua_ie_ipab/qua_ie_ipab_idc/qua_ie_ipab_idc.html', 'reviewed', '2026-11-22', 22);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('hk-residence', 'HK', 'import', 'both', NULL, 90, NULL, 0, '[]', 0, 0, 'Check your pet meets the "residence" rule', 'Hong Kong asks for confirmation that your pet has lived in the departure country for a set period right before travel (commonly 180 days, or since birth).', 'This shows your pet hasn’t recently been somewhere with a higher rabies risk.', 'Your vet confirms this on the health certificate. If your pet arrived in the departure country recently, contact AFCD before booking anything. For Group II places, AFCD also runs a "Residence Certification Waiver Scheme" — ask AFCD whether it applies to you.', NULL, NULL, 'https://www.afcd.gov.hk/english/quarantine/qua_ie/qua_ie_ipab/qua_ie_ipab_idc/qua_ie_ipab_idc_rcw.html', 'general', '2026-11-22', 23);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('hk-permit', 'HK', 'import', 'both', NULL, 14, NULL, 7, '[]', 0, 1, 'Apply for the AFCD Special Permit', 'Get a Special Permit from AFCD that allows your pet into Hong Kong. Each animal needs its own permit.', 'By law, no dog or cat can be brought into Hong Kong (even in transit) without a permit obtained in advance. Airlines will not take your pet without it.', 'Fill in the application forms (AF240 and UN110) from the AFCD website and submit them with the fee and a copy of your pet’s vaccination record. Once approved, AFCD sends the permit plus the exact health certificate form your vet must use (VC-DC2 for Group II).', 'Apply about 1–3 months before travel. Your permit lists the conditions to meet — read them carefully, as they are the final word.', 'An AFCD permit fee per animal (a few hundred HKD — check the current fee)', 'https://www.afcd.gov.hk/english/quarantine/qua_ie/qua_ie_ipab/qua_ie_ipab_idc/qua_ie_ipab_idc.html', 'reviewed', '2026-11-22', 24);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('hk-health-cert', 'HK', 'import', 'both', NULL, 3, 15, 0, '["hk-microchip","hk-rabies","hk-dog-vaccines","hk-permit"]', 0, 1, 'Vet health certificate (within 14 days of departure)', 'Your accredited vet examines your pet and fills in the Hong Kong animal health certificate that came with your permit.', 'This confirms your pet is healthy, vaccinated and microchipped right before travel. It is only valid for 14 days from the date it is issued.', 'Book this vet visit for no more than 14 days before your departure date, then leave enough time for the government endorsement in the next step.', 'Bring your permit, the blank certificate form, the rabies certificate and the microchip record to the appointment.', 'Vet exam and paperwork fee, often $150–$300', 'https://www.afcd.gov.hk/english/quarantine/qua_ie/qua_ie_ipab/qua_ie_ipab_idc/qua_ie_ipab_idc.html', 'reviewed', '2026-11-22', 25);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('hk-airline-cert', 'HK', 'import', 'both', NULL, 0, 1, 0, '[]', 0, 1, 'Ask for the airline certificate (captain’s affidavit)', 'The airline fills in a short form confirming your pet stayed on the plane and wasn’t in contact with other animals during the flight.', 'AFCD lists it as one of the required documents on arrival.', 'Remind your airline or pet relocation agent when booking that Hong Kong needs this form. It is completed by the airline on the day of travel.', NULL, NULL, 'https://www.afcd.gov.hk/english/quarantine/qua_ie/qua_ie_ipab/qua_ie_ipab_idc/qua_ie_ipab_idc.html', 'reviewed', '2026-11-22', 26);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('hk-arrival', 'HK', 'import', 'both', NULL, 0, 0, 0, '[]', 0, 1, 'Arrival: AFCD inspection and pick-up at HKIA', 'Your pet lands as cargo. AFCD officers check the documents, scan the microchip and look at your pet before releasing it.', 'This is the final check that every permit condition was met. Pets from Group I and II places that pass go home with you — no quarantine.', 'Your pet relocation agent (or you) collects your pet at the airport’s animal handling area after customs and AFCD clearance. Bring ID and copies of every document. Expect it to take a few hours after landing.', 'Arrange a pet taxi in advance — regular taxis may refuse large crates.', NULL, 'https://www.afcd.gov.hk/english/quarantine/qua_ie/qua_ie_ipab/qua_ie_ipab_idc/qua_ie_ipab_idc.html', 'reviewed', '2026-11-22', 27);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('hk-dog-licence', 'HK', 'import', 'dog', NULL, -30, NULL, 0, '[]', 0, 1, 'Get a Hong Kong dog licence', 'All dogs over 5 months old in Hong Kong need a licence and a valid rabies vaccine.', 'It is the law in Hong Kong, and the licence links your dog to you.', 'Visit an AFCD Animal Management Centre or a vet who offers licensing. Bring proof of rabies vaccination and your ID. The licence must be renewed along with the rabies vaccine.', NULL, NULL, 'https://www.afcd.gov.hk/english/quarantine/qua_vetlab/qua_vetlab_ah/qua_vetlab_ah_dog.html', 'reviewed', '2026-11-22', 28);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('ca-rabies', 'CA', 'import', 'both', '{"originGroups":["other"]}', 7, 365, 0, '[]', 0, 1, 'Rabies vaccination certificate', 'Cats and dogs 3 months or older need a valid rabies vaccination certificate signed by a vet.', 'Canada uses this to keep rabies out of the country.', 'The certificate must show your pet’s description, the vaccine name and serial number, the date given and how long it lasts. It must be in English or French.', NULL, 'About $40–$100 if a booster is needed', 'https://inspection.canada.ca/en/importing-food-plants-or-animals/pets/dogs-and-cats', 'general', '2026-11-22', 29);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('ca-rabies-recommended', 'CA', 'import', 'both', '{"originGroups":["rabies-free"]}', 7, NULL, 0, '[]', 0, 0, 'Rabies vaccine (recommended)', 'Coming from a rabies-free country, Canada may not ask for a rabies certificate, but a vaccine is still strongly recommended.', 'Rabies is present in Canadian wildlife, and many provinces, cities and boarding facilities require vaccination.', 'Ask your vet to vaccinate and keep the certificate with your travel documents.', NULL, NULL, 'https://inspection.canada.ca/en/importing-food-plants-or-animals/pets/dogs-and-cats', 'general', '2026-11-22', 30);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('ca-arrival', 'CA', 'import', 'both', NULL, 0, 0, 0, '[]', 0, 1, 'Arrival: border inspection', 'Declare your pet to the Canada Border Services Agency (CBSA) when you arrive.', 'The officer checks your documents and that your pet looks healthy.', 'Have the rabies certificate ready. A small inspection fee may be charged.', NULL, NULL, 'https://inspection.canada.ca/en/importing-food-plants-or-animals/pets/dogs-and-cats', 'general', '2026-11-22', 31);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('us-microchip', 'US', 'import', 'dog', NULL, 3, NULL, 0, '[]', 0, 1, 'Make sure your pet has an ISO microchip', 'Your pet needs a 15-digit microchip that meets the international ISO 11784/11785 standard.', 'The microchip proves that the animal arriving is the same one on the paperwork. It has to be put in before the rabies vaccine, or the vaccine may not count.', 'Ask your vet to scan your pet to confirm the chip is ISO-standard, or to implant one if not.', NULL, 'About $50–$100 if a new chip is needed', 'https://www.cdc.gov/importation/dogs/index.html', 'general', '2026-11-22', 32);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('us-dog-age', 'US', 'import', 'dog', NULL, 0, NULL, 0, '[]', 0, 0, 'Check your dog will be at least 6 months old', 'Every dog entering the US must be at least 6 months old on arrival.', 'This is part of the CDC rules introduced in August 2024 to stop rabies coming in.', 'If your dog is younger, move the arrival date later.', NULL, NULL, 'https://www.cdc.gov/importation/dogs/index.html', 'general', '2026-11-22', 33);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('us-dog-form', 'US', 'import', 'dog', NULL, 2, 10, 0, '["us-microchip"]', 0, 1, 'Submit the CDC Dog Import Form (2–10 days before arrival)', 'Fill in the free online CDC Dog Import Form and keep the receipt.', 'Airlines and US border officers will ask for the receipt. No receipt means your dog can be refused entry.', 'Fill it in on the CDC website between 2 and 10 days before arrival. You need a clear, recent photo of your dog and the microchip number. Print the receipt or save it on your phone.', NULL, 'Free', 'https://www.cdc.gov/importation/dogs/index.html', 'general', '2026-11-22', 34);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('us-health-cert', 'US', 'import', 'both', NULL, 3, 10, 0, '[]', 0, 0, 'Vet health check and rabies certificate (recommended)', 'Get a recent vet health certificate and keep your rabies certificate handy.', 'Cats have no federal paperwork, but many airlines and some states require a recent health certificate and proof of rabies vaccination.', 'Ask your vet for a health certificate within 10 days of travel and check your destination state’s rules (Hawaii has its own strict process).', NULL, NULL, 'https://www.aphis.usda.gov/pet-travel/another-country-to-us-import', 'general', '2026-11-22', 35);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('us-arrival', 'US', 'import', 'both', NULL, 0, 0, 0, '[]', 0, 1, 'Arrival: show documents at the border', 'Have your pet’s documents ready for US Customs and Border Protection.', 'Officers may check the Dog Import Form receipt, the microchip and your pet’s health.', 'Keep originals with you, not in checked luggage.', NULL, NULL, 'https://www.cdc.gov/importation/dogs/index.html', 'general', '2026-11-22', 36);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('gb-microchip', 'GB', 'import', 'both', NULL, 22, NULL, 0, '[]', 0, 1, 'Make sure your pet has an ISO microchip', 'Your pet needs a 15-digit microchip that meets the international ISO 11784/11785 standard.', 'The microchip proves that the animal arriving is the same one on the paperwork. It has to be put in before the rabies vaccine, or the vaccine may not count.', 'Ask your vet to scan your pet to confirm the chip is ISO-standard, or to implant one if not.', NULL, 'About $50–$100 if a new chip is needed', 'https://www.gov.uk/bring-pet-to-great-britain', 'general', '2026-11-22', 37);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('gb-rabies', 'GB', 'import', 'both', NULL, 22, NULL, 0, '["gb-microchip"]', 0, 1, 'Rabies vaccination (at least 21 days before travel)', 'Your pet must have a rabies vaccine at least 21 days before travel, given after the microchip.', 'Great Britain is rabies-free. The 21-day wait makes sure the vaccine has taken effect.', 'Get the vaccine and certificate from your vet. Keep boosters up to date — if it lapses you have to restart the 21 days.', NULL, 'About $40–$100', 'https://www.gov.uk/bring-pet-to-great-britain', 'general', '2026-11-22', 38);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('gb-approved-route', 'GB', 'import', 'both', NULL, 21, NULL, 3, '[]', 0, 1, 'Book an approved route into Great Britain', 'Pets must arrive by an approved airline and route — for most flights this means as cargo into an airport with an Animal Reception Centre (e.g. Heathrow).', 'Pets arriving any other way can be refused or quarantined.', 'Use the Airlines tab to find a carrier, and confirm with the airline or your agent that the route is approved for pets.', NULL, NULL, 'https://www.gov.uk/guidance/pet-travel-to-great-britain-approved-routes', 'general', '2026-11-22', 39);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('gb-ahc', 'GB', 'import', 'both', NULL, 2, 10, 0, '["gb-rabies"]', 0, 1, 'Get a health certificate (within 10 days of arrival)', 'An official vet issues a health certificate for entry into Great Britain.', 'This document proves the microchip, rabies vaccination and (for dogs) tapeworm treatment meet the rules.', 'Book your vet within 10 days of arrival. In some countries the government must also endorse it (see the export step).', NULL, 'Often $150–$300', 'https://www.gov.uk/bring-pet-to-great-britain', 'general', '2026-11-22', 40);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('gb-tapeworm', 'GB', 'import', 'dog', NULL, 1, 5, 0, '[]', 0, 1, 'Tapeworm treatment for dogs (1–5 days before arrival)', 'A vet must give your dog a tapeworm treatment between 24 hours and 120 hours (1–5 days) before arrival.', 'This stops a tapeworm that can harm people from entering Great Britain.', 'Book the vet visit so it falls 1–5 days before you land. The vet records the treatment on the health certificate.', 'Count the hours carefully against your landing time, including time zones.', NULL, 'https://www.gov.uk/bring-pet-to-great-britain', 'general', '2026-11-22', 41);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('gb-banned-breeds', 'GB', 'import', 'dog', NULL, 150, NULL, 0, '[]', 0, 0, 'Check your dog is not a banned type', 'Some dog types are banned in Great Britain, such as Pit Bull Terrier, Japanese Tosa, Dogo Argentino, Fila Brasileiro and XL Bully.', 'Banned dogs can be seized at the border.', 'If your dog might be one of these types, check GOV.UK before going any further.', NULL, NULL, 'https://www.gov.uk/control-dog-public/banned-dogs', 'general', '2026-11-22', 42);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('eu-microchip', 'EU', 'import', 'both', NULL, 22, NULL, 0, '[]', 0, 1, 'Make sure your pet has an ISO microchip', 'Your pet needs a 15-digit microchip that meets the international ISO 11784/11785 standard.', 'The microchip proves that the animal arriving is the same one on the paperwork. It has to be put in before the rabies vaccine, or the vaccine may not count.', 'Ask your vet to scan your pet to confirm the chip is ISO-standard, or to implant one if not.', NULL, 'About $50–$100 if a new chip is needed', 'https://food.ec.europa.eu/animals/movement-pets_en', 'general', '2026-11-22', 43);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('eu-rabies', 'EU', 'import', 'both', NULL, 22, NULL, 0, '["eu-microchip"]', 0, 1, 'Rabies vaccination (at least 21 days before travel)', 'Your pet must have a rabies vaccine at least 21 days before entering the EU, given after the microchip.', 'The EU uses this to stop rabies being imported.', 'Your vet gives the vaccine and records it with the microchip number.', NULL, 'About $40–$100', 'https://food.ec.europa.eu/animals/movement-pets_en', 'general', '2026-11-22', 44);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('eu-ahc', 'EU', 'import', 'both', NULL, 2, 10, 0, '["eu-rabies"]', 0, 1, 'EU animal health certificate (within 10 days of arrival)', 'Your vet fills in the official EU animal health certificate, which a government vet then endorses.', 'Without it, your pet cannot enter the EU. It is also valid for travel between EU countries for 4 months.', 'Book the vet within 10 days of arrival, then get it endorsed (see the export step).', 'Going to Ireland, Finland, Malta or Norway with a dog? You also need a tapeworm treatment 1–5 days before arrival.', 'Often $150–$300', 'https://food.ec.europa.eu/animals/movement-pets_en', 'general', '2026-11-22', 45);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('eu-arrival', 'EU', 'import', 'both', NULL, 0, 0, 0, '[]', 0, 1, 'Arrival: go through the pet check at customs', 'Enter through a travellers’ point of entry and show your pet’s documents to customs.', 'Pets must be checked on entry to the EU.', 'Use the "goods to declare" (red) channel if there is no specific pet desk.', NULL, NULL, 'https://food.ec.europa.eu/animals/movement-pets_en', 'general', '2026-11-22', 46);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('au-microchip', 'AU', 'import', 'both', NULL, 10, NULL, 0, '[]', 0, 1, 'Make sure your pet has an ISO microchip', 'Your pet needs a 15-digit microchip that meets the international ISO 11784/11785 standard.', 'The microchip proves that the animal arriving is the same one on the paperwork. It has to be put in before the rabies vaccine, or the vaccine may not count.', 'Ask your vet to scan your pet to confirm the chip is ISO-standard, or to implant one if not.', NULL, 'About $50–$100 if a new chip is needed', 'https://www.agriculture.gov.au/biosecurity-trade/cats-dogs', 'reviewed', '2026-11-22', 47);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('au-identity', 'AU', 'import', 'both', '{"originGroups":["group3"]}', 181, NULL, 0, '["au-microchip"]', 0, 0, 'Recommended: government identity check', 'A government vet in your departure country checks your pet’s microchip before export preparations start.', 'This cuts Australia’s quarantine from at least 30 days to at least 10 days.', 'Ask your vet to arrange it with the government vet service (e.g. CFIA or USDA) at least 180 days before export.', NULL, NULL, 'https://www.agriculture.gov.au/biosecurity-trade/cats-dogs/frequently-asked-questions', 'reviewed', '2026-11-22', 48);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('au-rabies', 'AU', 'import', 'both', '{"originGroups":["group3"]}', 30, NULL, 0, '["au-microchip"]', 0, 1, 'Rabies vaccination', 'Your pet must have a rabies vaccine, and it must still be valid on the day of export.', 'The vaccine is what makes the rabies blood test (next step) show protection.', 'Your vet vaccinates after the microchip is in. Keep it up to date until you travel.', NULL, 'About $40–$100', 'https://www.agriculture.gov.au/biosecurity-trade/cats-dogs/rabies-neutralising-antibody', 'reviewed', '2026-11-22', 49);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('au-rnatt', 'AU', 'import', 'both', '{"originGroups":["group3"]}', 181, 366, 0, '["au-rabies"]', 21, 1, 'Rabies blood test (RNATT) — at least 180 days before export', 'Your vet takes a blood sample and sends it to an approved lab to check the rabies vaccine worked (the "titer test" or RNATT).', 'This is the longest wait in the whole process: your pet must wait at least 180 days after the lab receives the sample before export. The result is valid for 12 months.', 'Book the blood draw at least 3–4 weeks after the rabies vaccine. Your vet sends it to a lab on Australia’s approved list. Results usually take 2–4 weeks.', 'Start as early as you can. This single step usually decides the earliest date you can move.', 'About $200–$400 including the lab fee', 'https://www.agriculture.gov.au/biosecurity-trade/cats-dogs/rabies-neutralising-antibody', 'reviewed', '2026-11-22', 50);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('au-rnatt-declaration', 'AU', 'import', 'both', '{"originGroups":["group3"]}', 60, NULL, 0, '["au-rnatt"]', 21, 1, 'Get the RNATT declaration endorsed by a government vet', 'A government vet in your departure country endorses the declaration with your pet’s blood test result.', 'Australia requires this endorsed declaration with your import permit application.', 'Once the lab result arrives, your vet completes the declaration form and sends it for government endorsement.', NULL, NULL, 'https://www.agriculture.gov.au/biosecurity-trade/cats-dogs/rabies-neutralising-antibody', 'reviewed', '2026-11-22', 51);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('au-permit', 'AU', 'import', 'both', NULL, 42, NULL, 28, '["au-rnatt-declaration"]', 0, 1, 'Apply for an Australian import permit', 'Apply online through BICON (Australia’s import system) for a permit to import your pet.', 'You cannot book quarantine or a flight to Australia without an import permit.', 'Create a BICON account, upload the RNATT declaration (if needed), vaccination records and microchip details, and pay the fee. Allow several weeks for processing.', NULL, 'Application fee of several hundred AUD (check current DAFF fees)', 'https://www.agriculture.gov.au/biosecurity-trade/cats-dogs/how-to-import', 'general', '2026-11-22', 52);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('au-peq-book', 'AU', 'import', 'both', NULL, 30, NULL, 3, '["au-permit"]', 0, 1, 'Book quarantine at the Mickleham facility (Melbourne)', 'Reserve your pet’s place at the Post-Entry Quarantine (PEQ) facility in Mickleham, Victoria.', 'All cats and dogs arriving in Australia stay there for at least 10 days. Spaces fill up quickly, especially around December–January.', 'Book online with DAFF as soon as you have your permit. Your arrival flight must land in Melbourne on the booked date.', NULL, 'Often AUD 2,000–2,500+ for a 10-day stay', 'https://www.agriculture.gov.au/biosecurity-trade/cats-dogs/post-entry-quarantine', 'general', '2026-11-22', 53);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('au-dog-tests', 'AU', 'import', 'dog', NULL, 10, 45, 7, '[]', 0, 1, 'Dog blood tests before export', 'Dogs need blood tests for several diseases (such as Ehrlichia, Leishmania and Brucella canis) in the weeks before export, as listed on your permit.', 'Australia is free of many dog diseases and checks dogs before they arrive.', 'Follow the exact list and timing on your import permit — ask your vet to plan these alongside the parasite treatments.', NULL, NULL, 'https://www.agriculture.gov.au/biosecurity-trade/cats-dogs/how-to-import', 'general', '2026-11-22', 54);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('au-parasites', 'AU', 'import', 'both', NULL, 2, 21, 0, '[]', 0, 1, 'Parasite treatments before export', 'Your pet needs internal (worms) and external (fleas/ticks) parasite treatments in the weeks before export.', 'This stops new parasites entering Australia.', 'Your import permit lists the exact products and timing — your vet records each treatment on the health certificate.', NULL, NULL, 'https://www.agriculture.gov.au/biosecurity-trade/cats-dogs/how-to-import', 'general', '2026-11-22', 55);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('au-health-cert', 'AU', 'import', 'both', NULL, 2, 6, 0, '["au-permit"]', 0, 1, 'Final vet check and health certificate', 'Your vet does the final checks and completes the Australian health certificate, which a government vet endorses.', 'Australia needs a certificate confirming every permit condition was met.', 'Book this within the few days before export allowed on your permit. Leave time for government endorsement.', NULL, 'Vet fees, often $200–$400', 'https://www.agriculture.gov.au/biosecurity-trade/cats-dogs/how-to-import', 'general', '2026-11-22', 56);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('au-arrival', 'AU', 'import', 'both', NULL, 0, 0, 0, '[]', 0, 1, 'Arrival in Melbourne and at least 10 days of quarantine', 'Your pet flies into Melbourne as cargo and is taken straight to the Mickleham quarantine facility.', 'Australia checks all imported pets in quarantine before releasing them.', 'You cannot collect your pet at the airport. Check the facility’s visiting rules, then pick your pet up at Mickleham when quarantine ends.', NULL, NULL, 'https://www.agriculture.gov.au/biosecurity-trade/cats-dogs/post-entry-quarantine', 'general', '2026-11-22', 57);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('jp-microchip', 'JP', 'import', 'both', NULL, 10, NULL, 0, '[]', 0, 1, 'Make sure your pet has an ISO microchip', 'Your pet needs a 15-digit microchip that meets the international ISO 11784/11785 standard.', 'The microchip proves that the animal arriving is the same one on the paperwork. It has to be put in before the rabies vaccine, or the vaccine may not count.', 'Ask your vet to scan your pet to confirm the chip is ISO-standard, or to implant one if not.', NULL, 'About $50–$100 if a new chip is needed', 'https://www.maff.go.jp/aqs/english/animal/dog/import-other.html', 'reviewed', '2026-11-22', 58);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('jp-rabies-1', 'JP', 'import', 'both', '{"originGroups":["non-designated"]}', 30, NULL, 0, '["jp-microchip"]', 0, 1, 'First rabies vaccination', 'The first of two rabies shots, given after the microchip. Your pet must be at least 91 days old.', 'Japan needs two rabies vaccinations to be sure your pet is protected.', 'If your pet already had a rabies vaccine after the microchip was implanted, it may count — show your records to your vet.', NULL, 'About $40–$100', 'https://www.maff.go.jp/aqs/english/animal/dog/import-other.html', 'reviewed', '2026-11-22', 59);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('jp-rabies-2', 'JP', 'import', 'both', '{"originGroups":["non-designated"]}', 30, NULL, 0, '["jp-rabies-1"]', 30, 1, 'Second rabies vaccination (at least 30 days after the first)', 'The second rabies shot, given at least 30 days after the first and while the first is still valid.', 'Two shots give the strong protection Japan requires before the blood test.', 'Book this with your vet about a month after the first shot.', NULL, 'About $40–$100', 'https://www.maff.go.jp/aqs/english/animal/dog/import-other.html', 'reviewed', '2026-11-22', 60);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('jp-rnatt', 'JP', 'import', 'both', '{"originGroups":["non-designated"]}', 180, 730, 0, '["jp-rabies-2"]', 0, 1, 'Rabies blood test — then a 180-day wait', 'Your vet takes a blood sample after the second rabies shot and sends it to a lab approved by Japan. The result must be at least 0.5 IU/ml.', 'Your pet can only arrive in Japan 180 days or more after this blood sample is taken. If you arrive earlier, your pet is quarantined at the airport to make up the difference.', 'Ask your vet to use a Japan-designated lab. Keep the lab result — it goes with your paperwork.', 'This 180-day wait usually decides the earliest date you can move.', 'About $200–$400 including the lab fee', 'https://www.maff.go.jp/aqs/english/animal/dog/import-other.html', 'reviewed', '2026-11-22', 61);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('jp-notice', 'JP', 'import', 'both', NULL, 40, NULL, 3, '[]', 0, 1, 'Notify the Animal Quarantine Service (at least 40 days before arrival)', 'Send an advance notification to the AQS office at your arrival airport.', 'In principle, notifications made less than 40 days before arrival are not accepted — and your pet could be refused.', 'Submit it online (NACCS) or by email/fax to the AQS office at your arrival airport. AQS will send back an approval you must bring with you.', NULL, 'Free', 'https://www.maff.go.jp/aqs/english/animal/dog/import-other.html', 'reviewed', '2026-11-22', 62);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('jp-health-cert', 'JP', 'import', 'both', NULL, 1, 3, 0, '[]', 0, 1, 'Health certificate signed close to departure', 'Your vet examines your pet just before departure and completes the certificate for Japan, which your government vet endorses.', 'Japan wants proof your pet is healthy and that all steps were done in order.', 'Use the certificate format from the AQS website. Plan the vet visit and the government endorsement very close to departure, and book both well in advance.', NULL, 'Vet fees, often $150–$300', 'https://www.maff.go.jp/aqs/english/animal/dog/import-other.html', 'general', '2026-11-22', 63);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('jp-arrival', 'JP', 'import', 'both', NULL, 0, 0, 0, '[]', 0, 1, 'Arrival: import inspection at the airport', 'The Animal Quarantine Service checks your pet and documents on arrival.', 'If everything is correct, your pet is usually released within about 12 hours. If not, quarantine can last up to 180 days.', 'Have your AQS approval, certificates and lab results ready.', NULL, NULL, 'https://www.maff.go.jp/aqs/english/animal/dog/import-other.html', 'general', '2026-11-22', 64);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('sg-microchip', 'SG', 'import', 'both', NULL, 10, NULL, 0, '[]', 0, 1, 'Make sure your pet has an ISO microchip', 'Your pet needs a 15-digit microchip that meets the international ISO 11784/11785 standard.', 'The microchip proves that the animal arriving is the same one on the paperwork. It has to be put in before the rabies vaccine, or the vaccine may not count.', 'Ask your vet to scan your pet to confirm the chip is ISO-standard, or to implant one if not.', NULL, 'About $50–$100 if a new chip is needed', 'https://avs.nparks.gov.sg/pets/importing-exporting-a-pet/import/dogs-and-cats/', 'general', '2026-11-22', 65);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('sg-check-schedule', 'SG', 'import', 'both', NULL, 150, NULL, 0, '[]', 0, 0, 'Check which AVS import conditions apply to you', 'Singapore updated its import rules in 2024 and groups countries by rabies risk. Find the "schedule" for your departure country.', 'Some departure countries need extra steps such as a rabies blood test with a waiting period. Knowing this early can change your whole timeline.', 'Use the country lookup on the AVS website, or the AVS live chat. Also check that your pet’s breed is allowed and, if you will live in an HDB flat, what HDB rules allow.', NULL, NULL, 'https://avs.nparks.gov.sg/pets/importing-exporting-a-pet/import/dogs-and-cats/', 'reviewed', '2026-11-22', 66);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('sg-rabies', 'SG', 'import', 'both', '{"originGroups":["other"]}', 30, 365, 0, '["sg-microchip"]', 0, 1, 'Rabies vaccination', 'Your pet needs a valid rabies vaccine given at least 30 days before arrival.', 'Singapore is rabies-free and protects that status carefully.', 'Your vet vaccinates after the microchip and gives you a signed certificate.', NULL, 'About $40–$100', 'https://avs.nparks.gov.sg/pets/importing-exporting-a-pet/import/dogs-and-cats/', 'general', '2026-11-22', 67);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('sg-pet-licence', 'SG', 'import', 'both', NULL, 40, NULL, 7, '[]', 0, 1, 'Apply for a Singapore dog or cat licence', 'Apply for a pet licence for your dog or cat on the AVS licensing portal.', 'You must have the pet licence before you can apply for the import licence.', 'Apply online on the AVS PALS portal with your pet’s microchip and vaccination details.', NULL, NULL, 'https://avs.nparks.gov.sg/pets/importing-exporting-a-pet/import/dogs-and-cats/', 'reviewed', '2026-11-22', 68);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('sg-import-licence', 'SG', 'import', 'both', NULL, 30, NULL, 7, '["sg-pet-licence"]', 0, 1, 'Apply for the AVS import licence', 'Apply for the licence to import your pet, and book its inspection or quarantine space.', 'Your pet cannot be accepted at Changi without it.', 'Apply on the AVS PALS portal after your pet licence is approved. Book the arrival inspection or quarantine slot as instructed.', NULL, 'AVS licence fees apply', 'https://avs.nparks.gov.sg/pets/importing-exporting-a-pet/import/dogs-and-cats/', 'reviewed', '2026-11-22', 69);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('sg-health-cert', 'SG', 'import', 'both', NULL, 2, 8, 0, '["sg-microchip"]', 0, 1, 'Health certificate endorsed by your government vet', 'Your vet completes Singapore’s veterinary certificate shortly before export, and the government vet endorses it.', 'This confirms your pet meets Singapore’s import conditions.', 'Use the certificate for your country’s schedule from the AVS website. Book the vet and the endorsement in advance.', NULL, 'Vet fees, often $150–$300', 'https://avs.nparks.gov.sg/pets/importing-exporting-a-pet/import/dogs-and-cats/', 'general', '2026-11-22', 70);
INSERT INTO requirements (id, country_code, direction, species, applies_if, deadline_days, window_days, duration_days, depends_on, gap_days, critical, title, what, why, how, tip, est_cost, official_url, verification, last_checked, sort_order) VALUES ('sg-arrival', 'SG', 'import', 'both', NULL, 0, 0, 0, '[]', 0, 1, 'Arrival at Changi as cargo', 'Your pet lands as cargo and is inspected at Changi Animal and Plant Quarantine.', 'This is the final check. Depending on your country’s category, there may be a short quarantine.', 'Bring your licences and certificates to collect your pet after inspection.', NULL, NULL, 'https://avs.nparks.gov.sg/pets/importing-exporting-a-pet/import/dogs-and-cats/', 'general', '2026-11-22', 71);
INSERT INTO airlines (code, name, policy_url, modes, serves, hub, snub_nosed, summary, cabin_note, cargo_note, heat_note, crate_note, booking_tip, verification, last_checked) VALUES ('CX', 'Cathay Pacific (Cathay Cargo)', 'https://www.cathaypacific.com/cx/en_HK/prepare-trip/help-for-passengers/travelling-with-animals.html', '["cargo"]', '["CA","HK","US","GB","EU","AU","SG","JP"]', 'Hong Kong (HKG)', 'restricted', 'Hong Kong’s home airline. Pets do not fly in the cabin; they travel in the hold as cargo through the "Cathay Live Animal" service.', NULL, 'Since 1 September 2025, Cathay Cargo only accepts pet bookings from IPATA/ATA members, IATA freight forwarders or people holding IATA Live Animal Regulations training — so in practice most owners book through a pet relocation agent.', 'Snub-nosed breeds are only accepted on certain routes and at Cathay’s discretion.', 'IATA-compliant crate required. Pets and documents are checked in at the cargo terminal about 4–6 hours before departure.', 'Bookings are usually only confirmed about a month before the flight, once space is known.', 'reviewed', '2026-11-22');
INSERT INTO airlines (code, name, policy_url, modes, serves, hub, snub_nosed, summary, cabin_note, cargo_note, heat_note, crate_note, booking_tip, verification, last_checked) VALUES ('AC', 'Air Canada (AC Animals)', 'https://www.aircanada.com/ca/en/aco/home/plan/special-assistance/pets.html', '["cabin","checked","cargo"]', '["CA","US","GB","EU","HK","JP","AU","SG"]', 'Toronto (YYZ), Vancouver (YVR), Montréal (YUL)', 'restricted', 'Canada’s largest airline. Small cats and dogs can fly in the cabin in a soft carrier on many routes. Larger pets, and pets going to cargo-only destinations, travel with AC Cargo’s "AC Animals" service.', 'One cat or small dog per passenger in a soft-sided carrier (required since 1 June 2025) that fits under the seat.', 'Contact AC Cargo (AC Animals) for rates, and for crates over 45 kg or 292 cm in total dimensions.', 'Pets are not carried in the hold to/from Hong Kong, China, Japan and Korea from 1 June to 30 September.', 'Hard-sided IATA crate for the hold. Some snub-nosed and strong breeds are restricted.', 'For in-cabin or checked pets, call Air Canada after booking your ticket. For cargo, contact AC Cargo or your agent.', 'reviewed', '2026-11-22');
INSERT INTO airlines (code, name, policy_url, modes, serves, hub, snub_nosed, summary, cabin_note, cargo_note, heat_note, crate_note, booking_tip, verification, last_checked) VALUES ('BA', 'British Airways (IAG Cargo)', 'https://www.britishairways.com/content/information/travel-assistance/travelling-with-pets', '["cargo"]', '["GB","US","CA","EU","HK","JP","SG","AU"]', 'London Heathrow (LHR)', 'restricted', 'Pets (other than assistance dogs) do not fly in the cabin. They travel as cargo with IAG Cargo, which is the usual route into Great Britain.', NULL, 'Book through IAG Cargo or an approved pet shipper.', 'Snub-nosed breeds may face seasonal or route restrictions.', NULL, 'Ask a pet relocation agent — they book IAG Cargo pet shipments daily.', 'general', '2026-11-22');
INSERT INTO airlines (code, name, policy_url, modes, serves, hub, snub_nosed, summary, cabin_note, cargo_note, heat_note, crate_note, booking_tip, verification, last_checked) VALUES ('SQ', 'Singapore Airlines (SIA Cargo)', 'https://www.singaporeair.com/en_UK/sg/travel-info/special-assistance/travelling-with-pets/', '["checked","cargo"]', '["SG","AU","GB","EU","US","JP","HK"]', 'Singapore (SIN)', 'restricted', 'Pets travel in the hold, either as checked baggage on some routes or as cargo. Pets entering Singapore must come as cargo.', NULL, NULL, NULL, NULL, 'Contact the airline or SIA Cargo well in advance; space is limited.', 'general', '2026-11-22');
INSERT INTO airlines (code, name, policy_url, modes, serves, hub, snub_nosed, summary, cabin_note, cargo_note, heat_note, crate_note, booking_tip, verification, last_checked) VALUES ('JL', 'Japan Airlines', 'https://www.jal.co.jp/jp/en/inter/service/pet/', '["checked","cargo"]', '["JP","US","CA","GB","EU","AU","SG","HK"]', 'Tokyo (HND / NRT)', 'restricted', 'Cats and dogs can travel in the hold as checked baggage on many international routes, or as cargo.', NULL, NULL, 'Snub-nosed breeds are restricted, especially in summer.', NULL, 'Reserve your pet’s space when booking your own ticket.', 'general', '2026-11-22');
INSERT INTO airlines (code, name, policy_url, modes, serves, hub, snub_nosed, summary, cabin_note, cargo_note, heat_note, crate_note, booking_tip, verification, last_checked) VALUES ('QF', 'Qantas (Qantas Freight)', 'https://www.qantas.com/au/en/travel-info/travel-with-pets.html', '["cargo"]', '["AU","US","GB","SG","JP","HK","CA"]', 'Sydney (SYD), Melbourne (MEL)', 'restricted', 'International pets travel as cargo with Qantas Freight. Pets entering Australia must land in Melbourne.', NULL, NULL, NULL, NULL, 'Usually booked by a pet relocation agent together with the Mickleham quarantine booking.', 'general', '2026-11-22');
INSERT INTO airlines (code, name, policy_url, modes, serves, hub, snub_nosed, summary, cabin_note, cargo_note, heat_note, crate_note, booking_tip, verification, last_checked) VALUES ('LH', 'Lufthansa', 'https://www.lufthansa.com/us/en/animals', '["cabin","checked","cargo"]', '["EU","US","CA","HK","JP","SG","GB"]', 'Frankfurt (FRA), Munich (MUC)', 'restricted', 'Small pets can fly in the cabin, larger pets in the hold or as cargo (Lufthansa Cargo).', 'Pet plus carrier usually up to 8 kg in the cabin.', NULL, NULL, NULL, 'Register your pet with Lufthansa right after booking your ticket.', 'general', '2026-11-22');
INSERT INTO airlines (code, name, policy_url, modes, serves, hub, snub_nosed, summary, cabin_note, cargo_note, heat_note, crate_note, booking_tip, verification, last_checked) VALUES ('AF', 'Air France / KLM', 'https://www.airfrance.com/information/preparation/voyager-avec-des-animaux', '["cabin","checked","cargo"]', '["EU","US","CA","JP","HK","SG","GB"]', 'Paris (CDG), Amsterdam (AMS)', 'banned', 'Small pets in the cabin, larger pets in the hold. Snub-nosed breeds are generally not accepted in the hold.', NULL, NULL, NULL, NULL, 'Add your pet to your booking as early as possible — there is a limit per flight.', 'general', '2026-11-22');
INSERT INTO airlines (code, name, policy_url, modes, serves, hub, snub_nosed, summary, cabin_note, cargo_note, heat_note, crate_note, booking_tip, verification, last_checked) VALUES ('EK', 'Emirates (Emirates SkyCargo)', 'https://www.emirates.com/english/before-you-fly/travel/travelling-with-pets/', '["cargo"]', '["CA","HK","US","GB","EU","AU","SG","JP"]', 'Dubai (DXB)', 'restricted', 'Pets travel only as cargo through Emirates SkyCargo, with temperature-controlled handling in Dubai.', NULL, NULL, NULL, NULL, 'Often used for long journeys with one stop in Dubai. Booked through SkyCargo or an agent.', 'general', '2026-11-22');
INSERT INTO airlines (code, name, policy_url, modes, serves, hub, snub_nosed, summary, cabin_note, cargo_note, heat_note, crate_note, booking_tip, verification, last_checked) VALUES ('UA', 'United Airlines', 'https://www.united.com/en/us/fly/travel/animals/pets.html', '["cabin"]', '["US","CA","GB","EU","JP","AU","SG","HK"]', 'Chicago, Newark, San Francisco and others', 'accepted', 'Small pets can fly in the cabin on many routes. United does not currently fly pets in the hold or as cargo.', NULL, NULL, NULL, NULL, 'Only useful if your destination allows pets in the cabin.', 'general', '2026-11-22');
INSERT INTO airlines (code, name, policy_url, modes, serves, hub, snub_nosed, summary, cabin_note, cargo_note, heat_note, crate_note, booking_tip, verification, last_checked) VALUES ('WS', 'WestJet', 'https://www.westjet.com/en-ca/travel-info/pets', '["cabin","checked"]', '["CA","US","GB","EU"]', 'Calgary (YYC), Toronto (YYZ)', 'restricted', 'Small pets in the cabin; limited checked-pet options on some routes.', NULL, NULL, NULL, NULL, 'Call WestJet to add your pet after booking.', 'general', '2026-11-22');
INSERT INTO airline_routes (airline_code, origin_code, dest_code, routing, note, rank) VALUES ('CX', 'CA', 'HK', 'Nonstop: Toronto (YYZ) → Hong Kong, Vancouver (YVR) → Hong Kong', 'The most direct option from Toronto: one ~16-hour flight with no transfer, so your pet is handled less.', 1);
INSERT INTO airline_routes (airline_code, origin_code, dest_code, routing, note, rank) VALUES ('AC', 'CA', 'HK', 'Nonstop from Vancouver; from Toronto check the current schedule (often via Vancouver)', 'Hong Kong only accepts pets as cargo, so book with AC Cargo (AC Animals), not as checked baggage. There is no hold service to Hong Kong from 1 June to 30 September.', 2);
INSERT INTO airline_routes (airline_code, origin_code, dest_code, routing, note, rank) VALUES ('CX', 'HK', 'CA', 'Nonstop: Hong Kong → Toronto (YYZ), Hong Kong → Vancouver (YVR)', 'Book through an agent registered with Cathay Cargo.', 3);
INSERT INTO airline_routes (airline_code, origin_code, dest_code, routing, note, rank) VALUES ('BA', 'CA', 'GB', 'Nonstop from Toronto, Vancouver, Montréal and Calgary to London Heathrow', 'Lands at Heathrow, which has the Animal Reception Centre.', 4);
INSERT INTO airline_routes (airline_code, origin_code, dest_code, routing, note, rank) VALUES ('QF', 'US', 'AU', 'Via Los Angeles / Dallas into Melbourne (or connecting via Sydney)', 'Your pet must land in Melbourne to go to Mickleham quarantine.', 5);
INSERT INTO glossary (term, aliases, explanation) VALUES ('ISO microchip', '["microchip","ISO 11784/11785"]', 'A tiny chip, about the size of a grain of rice, placed under your pet’s skin. It stores a 15-digit number that any international scanner can read. ISO is the international standard most countries require.');
INSERT INTO glossary (term, aliases, explanation) VALUES ('Rabies', '[]', 'A deadly virus spread through bites. Many places (like Hong Kong, the UK, Japan and Australia) are rabies-free, which is why their pet rules are so strict.');
INSERT INTO glossary (term, aliases, explanation) VALUES ('RNATT', '["titer test","rabies blood test","titre test"]', 'A blood test that measures whether the rabies vaccine worked. It must be done at an approved lab. Some countries then make you wait (often 180 days) before your pet can arrive.');
INSERT INTO glossary (term, aliases, explanation) VALUES ('Health certificate', '["animal health certificate","veterinary certificate"]', 'An official form your vet fills in shortly before travel, confirming your pet is healthy and meets the destination’s rules. It is only valid for a few days.');
INSERT INTO glossary (term, aliases, explanation) VALUES ('Endorse', '["endorsement","endorsed"]', 'When a government vet checks your vet’s paperwork and adds an official stamp or signature. Most countries won’t accept a certificate without it.');
INSERT INTO glossary (term, aliases, explanation) VALUES ('Accredited vet', '["accredited veterinarian"]', 'A regular vet who is also authorised by the government to sign export paperwork. Not every vet is — ask yours.');
INSERT INTO glossary (term, aliases, explanation) VALUES ('Official Veterinarian', '["government vet","official vet"]', 'A vet who works for, or is authorised by, the government to approve export documents.');
INSERT INTO glossary (term, aliases, explanation) VALUES ('CFIA', '[]', 'Canadian Food Inspection Agency — the Canadian government body that endorses pet export certificates and sets the rules for pets entering Canada.');
INSERT INTO glossary (term, aliases, explanation) VALUES ('AFCD', '[]', 'Agriculture, Fisheries and Conservation Department — the Hong Kong government department that issues pet import permits and inspects animals on arrival.');
INSERT INTO glossary (term, aliases, explanation) VALUES ('Special Permit', '[]', 'The permit Hong Kong’s AFCD must issue before any dog or cat can enter Hong Kong. Each animal needs its own.');
INSERT INTO glossary (term, aliases, explanation) VALUES ('USDA APHIS', '["APHIS","VEHCS"]', 'The US Department of Agriculture’s animal health service. It endorses export health certificates for pets leaving the US, often online through a system called VEHCS.');
INSERT INTO glossary (term, aliases, explanation) VALUES ('APHA', '[]', 'Animal and Plant Health Agency — the UK government body for pet import and export paperwork.');
INSERT INTO glossary (term, aliases, explanation) VALUES ('DAFF', '["BICON"]', 'Australia’s Department of Agriculture, Fisheries and Forestry. You apply for an Australian pet import permit through its online system, BICON.');
INSERT INTO glossary (term, aliases, explanation) VALUES ('AQS', '["Animal Quarantine Service"]', 'Japan’s Animal Quarantine Service, which approves pets coming into and leaving Japan.');
INSERT INTO glossary (term, aliases, explanation) VALUES ('AVS', '[]', 'Singapore’s Animal & Veterinary Service (part of NParks), which issues pet and import licences.');
INSERT INTO glossary (term, aliases, explanation) VALUES ('Manifest cargo', '["manifested cargo","cargo","air cargo"]', 'Your pet flies in the plane’s temperature- and pressure-controlled hold as a cargo shipment with its own air waybill, booked separately from your ticket. It might even be on a different flight from you.');
INSERT INTO glossary (term, aliases, explanation) VALUES ('Checked baggage', '["excess baggage"]', 'Your pet flies in the hold of your own flight and is checked in at the passenger desk, like a suitcase but with special handling.');
INSERT INTO glossary (term, aliases, explanation) VALUES ('In cabin', '["cabin"]', 'A small pet travels with you inside the cabin, in a carrier under the seat in front. Many destinations (Hong Kong, UK, Australia) don’t allow this for arrivals.');
INSERT INTO glossary (term, aliases, explanation) VALUES ('IATA crate', '["IATA","Live Animal Regulations","LAR"]', 'A travel crate that meets the International Air Transport Association’s rules for live animals: rigid, well ventilated, secure door, big enough for your pet to stand and turn around.');
INSERT INTO glossary (term, aliases, explanation) VALUES ('IPATA', '["pet relocation agent","pet shipper"]', 'The International Pet and Animal Transportation Association — a professional body for pet relocation companies. Members can handle the bookings, paperwork and airport steps for you.');
INSERT INTO glossary (term, aliases, explanation) VALUES ('Captain’s affidavit', '["airline certificate"]', 'A form completed by the airline confirming your pet stayed on board and had no contact with other animals during the flight. Hong Kong asks for it.');
INSERT INTO glossary (term, aliases, explanation) VALUES ('Quarantine', '["post-entry quarantine","PEQ"]', 'A period where your pet stays at a government facility after arrival so officials can watch for disease. Some countries need none, others (like Australia) at least 10 days.');
INSERT INTO glossary (term, aliases, explanation) VALUES ('Brachycephalic', '["snub-nosed","flat-faced"]', 'Breeds with short, flat faces (Persian, Himalayan, Pug, French Bulldog, etc.). They can struggle to breathe in heat or stress, so many airlines limit or ban them in the hold.');
INSERT INTO glossary (term, aliases, explanation) VALUES ('Heat embargo', '[]', 'A period, usually in summer, when an airline won’t carry pets in the hold on certain routes because of high temperatures.');
INSERT INTO glossary (term, aliases, explanation) VALUES ('Residence period', '["residence rule"]', 'A rule that your pet must have lived in the departure country for a set time (often 180 days, or since birth) right before travel.');
INSERT INTO glossary (term, aliases, explanation) VALUES ('Tapeworm treatment', '[]', 'A worming medicine given by a vet. Some places (UK, Ireland, Finland, Malta, Norway) require it for dogs 1–5 days before arrival.');
